/* ---------------- widgets ---------------- */
function onTheory(root){
 const w=root.querySelector('#w-drill');
 if(w){w.innerHTML=`<b>🚀 Путешествие к центру Земли: двигай бур</b>${SL('dD','Глубина:',0,6371,1,20)}<div id="dP" class="fig"></div><div id="dT" style="text-align:center;line-height:1.7"></div>`;
  const g=id=>w.querySelector('#'+id);const u=()=>{const d=+g('dD').value;g('dDo').textContent=N(d)+' км';const L=layerAt(d);
   g('dP').innerHTML=figEarth({drill:d,hl:L.n});
   g('dT').innerHTML=`Ты в слое: <span class="out">${L.n}</span><br>Состояние: <b>${L.st}</b> · Температура: <b>${L.t}</b>${d<=13?'<br><span class="small">Глубже всех люди пробурили Кольскую скважину — 12 км. Это даже не вся кора!</span>':''}`;};
  g('dD').oninput=u;u();}
 const m=root.querySelector('#w-mine');
 if(m){m.innerHTML=`<b>⛏ Шахта-термометр</b>${SL('mT','Температура у поверхности:',0,15,1,8)}${SL('mD','Глубина шахты:',0,4000,100,1000)}<div id="mP" class="fig"></div><div id="mX" style="text-align:center;line-height:1.7"></div>`;
  const g=id=>m.querySelector('#'+id);const u=()=>{const t0=+g('mT').value,d=+g('mD').value;g('mTo').textContent=sgn(t0)+' °C';g('mDo').textContent=N(d)+' м';const k=d/100,t=t0+3*k;
   g('mP').innerHTML=figMine(d,t0,t);g('mX').innerHTML=`${N(d)} м : 100 = <b>${N(k)}</b> · 3 °C = <b>${N(3*k)} °C</b> → ${sgn(t0)} + ${N(3*k)} = <span class="out">${sgn(t)} °C</span>${t>=100?'<br>Вода в такой шахте закипела бы!':''}`;};
  g('mT').oninput=u;g('mD').oninput=u;u();}
}

